package com.tickfishing;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class TickFishingPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(TickFishingPlugin.class);
		RuneLite.main(args);
	}
}

package com.tickfishing;

import java.util.Set;

final class ItemIds
{
	static final int KNIFE = 946;
	static final int SWAMP_TAR = 1939;
	static final int PESTLE_AND_MORTAR = 233;
	static final int ROE = 11324;
	static final int CAVIAR = 11326;

	// Clean low-level herbs usable for herb+tar: guam through irit
	static final Set<Integer> HERBS = Set.of(249, 251, 253, 255, 257, 2998, 259);

	// Normal, oak, willow, maple, yew, magic, mahogany, teak
	static final Set<Integer> LOGS = Set.of(1511, 1521, 1519, 1517, 1515, 1513, 6332, 6333);

	// Leaping trout, leaping salmon, leaping sturgeon
	static final Set<Integer> LEAPING_FISH = Set.of(11328, 11330, 11332);

	private ItemIds()
	{
	}
}

package com.tickfishing;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.NPC;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

class FishingSpotOverlay extends Overlay
{
	private final TickFishingPlugin plugin;
	private final TickFishingConfig config;

	@Inject
	FishingSpotOverlay(TickFishingPlugin plugin, TickFishingConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.highlightFishingSpots())
		{
			return null;
		}

		Color color = plugin.currentStep() == Step.SPOT
			? config.actionColor()
			: config.secondaryColor();

		for (NPC npc : plugin.getFishingSpots())
		{
			Shape hull = npc.getConvexHull();
			if (hull != null)
			{
				OverlayUtil.renderPolygon(graphics, hull, color);
			}
		}
		return null;
	}
}

package com.tickfishing;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

class TickFishingOverlay extends OverlayPanel
{
	private static final Color DONE_COLOR = new Color(140, 140, 140);

	private final TickFishingPlugin plugin;
	private final TickFishingConfig config;

	@Inject
	TickFishingOverlay(TickFishingPlugin plugin, TickFishingConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_CENTER);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.shouldShowOverlays())
		{
			return null;
		}

		int len = plugin.cycleLength();
		int tick = plugin.getTickInCycle();

		String title;
		Color titleColor;
		if (!plugin.isSynced())
		{
			title = "3T Fishing - waiting";
			titleColor = Color.LIGHT_GRAY;
		}
		else
		{
			title = "Tick " + (tick + 1) + " / " + len;
			titleColor = tick == 0 ? config.actionColor() : config.secondaryColor();
		}

		panelComponent.getChildren().add(TitleComponent.builder()
			.text(title)
			.color(titleColor)
			.build());

		String alert = plugin.activeAlert();
		if (alert != null)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("! " + alert)
				.leftColor(Color.RED)
				.build());
		}

		String missing = plugin.missingSupplies();
		if (missing != null)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("! " + missing)
				.leftColor(Color.RED)
				.build());
		}

		if (plugin.eatSoon())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Eat mode soon: " + plugin.getRoeCount() + "/" + config.roeThreshold() + " roe")
				.leftColor(config.eatWarningColor())
				.build());
		}

		if (plugin.isSynced())
		{
			// Pip row showing position in the cycle, e.g. O - -
			StringBuilder pips = new StringBuilder();
			for (int i = 0; i < len; i++)
			{
				pips.append(i == tick ? 'O' : '-');
				if (i < len - 1)
				{
					pips.append(' ');
				}
			}
			panelComponent.getChildren().add(TitleComponent.builder()
				.text(pips.toString())
				.color(titleColor)
				.build());
		}

		if (config.showClickSequence())
		{
			List<Step> sequence = plugin.getSequence();
			int stepIndex = plugin.getStepIndex();

			if (stepIndex >= sequence.size())
			{
				int ticksLeft = plugin.cycleLength() - plugin.getTickInCycle();
				panelComponent.getChildren().add(LineComponent.builder()
					.left("On tick - next cycle in " + ticksLeft)
					.leftColor(Color.WHITE)
					.build());
			}
			else
			{
				for (int i = 0; i < sequence.size(); i++)
				{
					Color color;
					String prefix;
					if (i < stepIndex)
					{
						color = DONE_COLOR;
						prefix = "* ";
					}
					else if (i == stepIndex)
					{
						color = config.actionColor();
						prefix = "> ";
					}
					else
					{
						color = Color.WHITE;
						prefix = "   ";
					}
					panelComponent.getChildren().add(LineComponent.builder()
						.left(prefix + sequence.get(i).instruction())
						.leftColor(color)
						.build());
				}
			}
		}

		if (config.showRhythm() && !plugin.getRecentIntervals().isEmpty())
		{
			List<Integer> intervals = plugin.getRecentIntervals();
			StringBuilder history = new StringBuilder();
			for (int interval : intervals)
			{
				if (history.length() > 0)
				{
					history.append(' ');
				}
				history.append(interval);
			}
			boolean lastOnTick = intervals.get(intervals.size() - 1) % plugin.cycleLength() == 0;
			panelComponent.getChildren().add(LineComponent.builder()
				.left(history.toString())
				.leftColor(lastOnTick ? Color.GREEN : Color.RED)
				.right("x" + plugin.getRhythmStreak())
				.rightColor(Color.WHITE)
				.build());
		}

		panelComponent.setPreferredSize(new Dimension(180, 0));
		return super.render(graphics);
	}
}

package com.tickfishing;

/**
 * One click in the 3-tick cycle, in the order the player must perform them.
 */
enum Step
{
	KNIFE("Click knife"),
	LOG("Use knife on log"),
	// Herb and tar can be combined in either click order, so both clicks of
	// the pair map onto this same step and it appears twice in the sequence.
	MIX("Combine herb + tar"),
	FISH("Use knife on fish"),
	EAT("Eat roe/caviar"),
	SPOT("Click fishing spot"),
	// Drop mode only: fish are dropped whole, cutting is exclusive to eat mode
	DROP("Drop fish");

	private final String instruction;

	Step(String instruction)
	{
		this.instruction = instruction;
	}

	String instruction()
	{
		return instruction;
	}
}

package com.tickfishing;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.StatChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "3-Tick Fishing Helper",
	description = "Click-by-click guide and tick metronome for 3-tick barbarian fishing",
	tags = {"fishing", "tick", "barbarian", "skilling", "metronome"}
)
public class TickFishingPlugin extends Plugin
{
	// GE quantity increment/decrement plops - short, distinct clicks that work well as a metronome
	private static final int SOUND_TICK = 898;
	private static final int SOUND_ACTION_TICK = 899;

	// Cap so ticksSinceXpDrop can be incremented forever without overflowing
	private static final int TICKS_IDLE_CAP = 1_000_000;

	private static final int ALERT_DURATION_TICKS = 10;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private TickFishingConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private TickFishingOverlay overlay;

	@Inject
	private InventoryHighlightOverlay inventoryOverlay;

	@Inject
	private FishingSpotOverlay spotOverlay;

	/**
	 * 0-based position in the tick cycle. Tick 0 is the XP-drop tick, which is
	 * also the tick the skilling timer must be re-delayed (knife-log or eat).
	 */
	@Getter
	private int tickInCycle;

	@Getter
	private int ticksSinceXpDrop = TICKS_IDLE_CAP;

	@Getter
	private final List<NPC> fishingSpots = new ArrayList<>();

	/**
	 * The ordered clicks for the current cycle; stepIndex points at the next
	 * one the player should perform.
	 */
	@Getter
	private final List<Step> sequence = new ArrayList<>();

	@Getter
	private int stepIndex;

	@Getter
	private int roeCount;

	/**
	 * Tick gaps between recent Fishing XP drops, oldest first. Exactly
	 * cycleLength (or a multiple, for failed rolls) means the player stayed
	 * on tick; anything else means the timer delay landed late.
	 */
	@Getter
	private final List<Integer> recentIntervals = new ArrayList<>();

	@Getter
	private int rhythmStreak;

	private int fishCount;
	private boolean hasKnife;
	private boolean hasLog;
	private boolean hasHerb;
	private boolean hasTar;
	private boolean hasPestle;

	private int lastFishingXp = -1;
	private int lastFletchingXp = -1;
	private int lastHerbloreXp = -1;
	private boolean xpDropThisTick;

	private String alertMessage;
	private int alertTicksRemaining;

	@Provides
	TickFishingConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(TickFishingConfig.class);
	}

	@Override
	protected void startUp()
	{
		reset();
		overlayManager.add(overlay);
		overlayManager.add(inventoryOverlay);
		overlayManager.add(spotOverlay);
		clientThread.invokeLater(this::rebuildSequence);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(inventoryOverlay);
		overlayManager.remove(spotOverlay);
		fishingSpots.clear();
		sequence.clear();
	}

	private void reset()
	{
		tickInCycle = 0;
		ticksSinceXpDrop = TICKS_IDLE_CAP;
		lastFishingXp = -1;
		lastFletchingXp = -1;
		lastHerbloreXp = -1;
		xpDropThisTick = false;
		sequence.clear();
		stepIndex = 0;
		alertTicksRemaining = 0;
		recentIntervals.clear();
		rhythmStreak = 0;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			reset();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if ("tickfishing".equals(event.getGroup()))
		{
			clientThread.invokeLater(this::rebuildSequence);
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		int xp = event.getXp();
		switch (event.getSkill())
		{
			case FISHING:
				// last xp < 0 means the initial stat sync on login, not a catch
				if (lastFishingXp >= 0 && xp > lastFishingXp)
				{
					xpDropThisTick = true;
				}
				lastFishingXp = xp;
				break;
			case FLETCHING:
				// Fletching XP means the knife-log action completed instead of
				// being interrupted: the log is now a stock, and the cycle broke.
				if (lastFletchingXp >= 0 && xp > lastFletchingXp)
				{
					setAlert("Fletched the log into a stock!");
				}
				lastFletchingXp = xp;
				break;
			case HERBLORE:
				// Same failure for the herb+tar method: the combine completed.
				if (lastHerbloreXp >= 0 && xp > lastHerbloreXp)
				{
					setAlert("Herb + tar combine completed!");
				}
				lastHerbloreXp = xp;
				break;
			default:
				break;
		}
	}

	private void setAlert(String message)
	{
		alertMessage = message;
		alertTicksRemaining = ALERT_DURATION_TICKS;
	}

	private void recordInterval(int interval)
	{
		// Ignore the first catch of a session and gaps from walking around
		if (interval > cycleLength() * 4)
		{
			return;
		}
		recentIntervals.add(interval);
		if (recentIntervals.size() > 8)
		{
			recentIntervals.remove(0);
		}
		rhythmStreak = interval % cycleLength() == 0 ? rhythmStreak + 1 : 0;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		updateInventoryState();

		if (alertTicksRemaining > 0)
		{
			alertTicksRemaining--;
		}

		if (xpDropThisTick)
		{
			recordInterval(ticksSinceXpDrop + 1);
			// The XP drop anchors the cycle: this tick the skilling timer is 0,
			// so the timer delay (knife-log or eat) must happen right now.
			tickInCycle = 0;
			ticksSinceXpDrop = 0;
			xpDropThisTick = false;
			rebuildSequence();
		}
		else
		{
			tickInCycle = (tickInCycle + 1) % cycleLength();
			ticksSinceXpDrop = Math.min(ticksSinceXpDrop + 1, TICKS_IDLE_CAP);
			// A failed catch roll gives no XP drop, but the cycle continues:
			// when the metronome wraps while synced, a new cycle has started
			// and the timer delay is due again right now. When unsynced there
			// is no beat to wait for, so loop as soon as the clicks are done.
			if (sequence.isEmpty()
				|| (tickInCycle == 0 && isSynced())
				|| (!isSynced() && stepIndex >= sequence.size()))
			{
				rebuildSequence();
			}
		}

		updateFishingSpots();
		playTickSound();
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		MenuEntry entry = event.getMenuEntry();
		Step clicked = classifyClick(entry);
		if (clicked == null)
		{
			return;
		}

		// Finished the whole cycle already? A fresh timer-delay click means the
		// player is starting the next cycle manually - resync to them.
		if (stepIndex >= sequence.size()
			&& (clicked == Step.KNIFE || clicked == Step.MIX || clicked == Step.EAT))
		{
			rebuildSequence();
		}

		// Lenient matching: advance to just past the first pending step this
		// click satisfies, so a skipped step doesn't wedge the guide.
		for (int i = stepIndex; i < sequence.size(); i++)
		{
			if (sequence.get(i) == clicked)
			{
				stepIndex = i + 1;
				break;
			}
		}
	}

	/**
	 * Maps a raw menu click onto the Step it represents, or null if unrelated.
	 */
	private Step classifyClick(MenuEntry entry)
	{
		NPC npc = entry.getNpc();
		if (npc != null)
		{
			String name = npc.getName();
			return name != null && name.toLowerCase().contains("fishing spot") ? Step.SPOT : null;
		}

		String option = entry.getOption();
		int itemId = entry.getItemId();

		if ("Eat".equals(option) && (itemId == ItemIds.ROE || itemId == ItemIds.CAVIAR))
		{
			return Step.EAT;
		}

		if ("Drop".equals(option) && ItemIds.LEAPING_FISH.contains(itemId))
		{
			return Step.DROP;
		}

		if ("Use".equals(option))
		{
			if (itemId == ItemIds.KNIFE)
			{
				return Step.KNIFE;
			}
			if (ItemIds.LOGS.contains(itemId))
			{
				return Step.LOG;
			}
			// Either half of the herb+tar pair counts, in either click order
			if (ItemIds.HERBS.contains(itemId) || itemId == ItemIds.SWAMP_TAR)
			{
				return Step.MIX;
			}
			if (ItemIds.LEAPING_FISH.contains(itemId))
			{
				return Step.FISH;
			}
		}

		return null;
	}

	private void updateInventoryState()
	{
		fishCount = 0;
		roeCount = 0;
		hasKnife = false;
		hasLog = false;
		hasHerb = false;
		hasTar = false;
		hasPestle = false;

		ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
		if (inventory == null)
		{
			return;
		}

		for (Item item : inventory.getItems())
		{
			int id = item.getId();
			if (ItemIds.LEAPING_FISH.contains(id))
			{
				fishCount++;
			}
			else if (id == ItemIds.ROE || id == ItemIds.CAVIAR)
			{
				roeCount += item.getQuantity();
			}
			else if (id == ItemIds.KNIFE)
			{
				hasKnife = true;
			}
			else if (ItemIds.LOGS.contains(id))
			{
				hasLog = true;
			}
			else if (ItemIds.HERBS.contains(id))
			{
				hasHerb = true;
			}
			else if (id == ItemIds.SWAMP_TAR)
			{
				hasTar = true;
			}
			else if (id == ItemIds.PESTLE_AND_MORTAR)
			{
				hasPestle = true;
			}
		}
	}

	/**
	 * Builds the click list for a fresh cycle from the current inventory:
	 * timer delay (eat, or knife+log / herb+tar), cut the held fish, click spot.
	 */
	private void rebuildSequence()
	{
		updateInventoryState();

		sequence.clear();
		stepIndex = 0;

		boolean eatNow = config.eatRoe() && roeCount >= config.roeThreshold();
		if (eatNow)
		{
			sequence.add(Step.EAT);
		}
		else if (config.timerMethod() == TickFishingConfig.TimerMethod.HERB_TAR)
		{
			sequence.add(Step.MIX);
			sequence.add(Step.MIX);
		}
		else
		{
			sequence.add(Step.KNIFE);
			sequence.add(Step.LOG);
		}

		if (fishCount > 0)
		{
			if (config.eatRoe())
			{
				// Cutting is exclusive to eat mode - it's what builds the
				// roe/caviar that eventually becomes the timer step
				sequence.add(Step.KNIFE);
				sequence.add(Step.FISH);
			}
			else
			{
				sequence.add(Step.DROP);
			}
		}

		sequence.add(Step.SPOT);
	}

	private void updateFishingSpots()
	{
		fishingSpots.clear();
		for (NPC npc : client.getNpcs())
		{
			String name = npc.getName();
			if (name != null && name.toLowerCase().contains("fishing spot"))
			{
				fishingSpots.add(npc);
			}
		}
	}

	private void playTickSound()
	{
		if (!config.tickSound() || !isSynced() || config.soundVolume() <= 0)
		{
			return;
		}
		int soundId = tickInCycle == 0 ? SOUND_ACTION_TICK : SOUND_TICK;
		client.playSoundEffect(soundId, config.soundVolume());
	}

	int cycleLength()
	{
		return Math.max(2, config.cycleLength());
	}

	/**
	 * The next click the player should perform, or null when the cycle is
	 * complete and they should wait for the XP drop.
	 */
	Step currentStep()
	{
		return stepIndex < sequence.size() ? sequence.get(stepIndex) : null;
	}

	/**
	 * Synced means we've seen a Fishing XP drop recently, so the metronome
	 * position is trustworthy.
	 */
	boolean isSynced()
	{
		return ticksSinceXpDrop <= config.idleTimeout();
	}

	boolean shouldShowOverlays()
	{
		return client.getGameState() == GameState.LOGGED_IN
			&& (isSynced() || !fishingSpots.isEmpty());
	}

	/**
	 * Accident alert (completed fletch / completed herb tar), or null when none
	 * is active.
	 */
	String activeAlert()
	{
		return alertTicksRemaining > 0 ? alertMessage : null;
	}

	/**
	 * Items the current method needs but the inventory lacks, or null if
	 * everything is present.
	 */
	String missingSupplies()
	{
		List<String> missing = new ArrayList<>();
		boolean eating = !sequence.isEmpty() && sequence.get(0) == Step.EAT;

		if (!eating)
		{
			if (config.timerMethod() == TickFishingConfig.TimerMethod.HERB_TAR)
			{
				if (!hasHerb)
				{
					missing.add("herb");
				}
				if (!hasTar)
				{
					missing.add("swamp tar");
				}
				if (!hasPestle)
				{
					missing.add("pestle & mortar");
				}
			}
			else if (!hasLog)
			{
				missing.add("log");
			}
		}

		boolean needsKnife = (config.eatRoe() && fishCount > 0)
			|| (!eating && config.timerMethod() == TickFishingConfig.TimerMethod.KNIFE_LOG);
		if (needsKnife && !hasKnife)
		{
			missing.add("knife");
		}

		return missing.isEmpty() ? null : "Missing: " + String.join(", ", missing);
	}

	/**
	 * True when eat mode is about to take over the timer step (within ~2
	 * catches of the threshold) but hasn't yet - so the switch isn't a surprise.
	 */
	boolean eatSoon()
	{
		if (!config.eatRoe() || !config.showEatWarning())
		{
			return false;
		}
		if (!sequence.isEmpty() && sequence.get(0) == Step.EAT)
		{
			return false;
		}
		return roeCount >= Math.max(1, config.roeThreshold() - 2);
	}
}

package com.tickfishing;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("tickfishing")
public interface TickFishingConfig extends Config
{
	enum TimerMethod
	{
		KNIFE_LOG("Knife + log"),
		HERB_TAR("Herb + tar");

