package com.tickfishing;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.ui.overlay.components.TextComponent;

class InventoryHighlightOverlay extends WidgetItemOverlay
{
	private final TickFishingPlugin plugin;
	private final TickFishingConfig config;

	@Inject
	InventoryHighlightOverlay(TickFishingPlugin plugin, TickFishingConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		showOnInventory();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!config.highlightInventory() || !plugin.shouldShowOverlays())
		{
			return;
		}

		List<Step> sequence = plugin.getSequence();
		int stepIndex = plugin.getStepIndex();
		Rectangle bounds = widgetItem.getCanvasBounds();
		boolean isRoe = itemId == ItemIds.ROE || itemId == ItemIds.CAVIAR;

		Color color = null;
		if (stepIndex < sequence.size() && stepMatchesItem(sequence.get(stepIndex), itemId))
		{
			color = config.actionColor();
		}
		else if (stepIndex + 1 < sequence.size() && stepMatchesItem(sequence.get(stepIndex + 1), itemId))
		{
			// Preview the click after this one with a dimmer outline
			color = config.secondaryColor();
		}
		else if (plugin.eatSoon() && isRoe)
		{
			// Heads-up that this stack is about to become the timer step
			color = config.eatWarningColor();
		}

		if (color != null)
		{
			graphics.setColor(color);
			graphics.draw(bounds);
			graphics.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), 40));
			graphics.fill(bounds);
		}

		// Progress toward the eat threshold, drawn on the food like a charge count
		if (isRoe && config.eatRoe() && config.showEatWarning())
		{
			TextComponent text = new TextComponent();
			text.setPosition(new Point(bounds.x, bounds.y + graphics.getFontMetrics().getHeight()));
			text.setText(plugin.getRoeCount() + "/" + config.roeThreshold());
			text.setColor(plugin.eatSoon() ? config.eatWarningColor() : Color.WHITE);
			text.render(graphics);
		}
	}

	private static boolean stepMatchesItem(Step step, int itemId)
	{
		switch (step)
		{
			case KNIFE:
				return itemId == ItemIds.KNIFE;
			case LOG:
				return ItemIds.LOGS.contains(itemId);
			case MIX:
				return ItemIds.HERBS.contains(itemId) || itemId == ItemIds.SWAMP_TAR;
			case FISH:
			case DROP:
				return ItemIds.LEAPING_FISH.contains(itemId);
			case EAT:
				return itemId == ItemIds.ROE || itemId == ItemIds.CAVIAR;
			default:
				return false;
		}
	}
}
